<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Security\SecretDigester;
use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;
use PHPUnit\Framework\TestCase;

#[AllowMockObjectsWithoutExpectations]
final class SecretDigesterUnitTest extends TestCase
{
    public function test_digest_is_deterministic_and_versioned(): void
    {
        $digester = new SecretDigester(['p1' => 'pepper-one'], 'p1');

        $one = $digester->digest('s3cret');

        $this->assertStringStartsWith('hmac-sha256:p1:', $one);
        $this->assertEquals($one, $digester->digest('s3cret'));
        $this->assertNotEquals($one, $digester->digest('other'));
        $this->assertStringNotContainsString('s3cret', $one);
    }

    public function test_verify(): void
    {
        $digester = new SecretDigester(['p1' => 'pepper-one'], 'p1');
        $stored = $digester->digest('s3cret');

        $this->assertTrue($digester->verify('s3cret', $stored));
        $this->assertFalse($digester->verify('S3cret', $stored));
        $this->assertFalse($digester->needsRehash($stored));
    }

    public function test_pepper_is_part_of_the_digest(): void
    {
        $one = (new SecretDigester(['p1' => 'pepper-one'], 'p1'))->digest('s3cret');
        $other = (new SecretDigester(['p1' => 'pepper-other'], 'p1'))->digest('s3cret');

        $this->assertNotEquals($one, $other);
    }

    public function test_rotation_keeps_old_digests_verifiable_and_flags_rehash(): void
    {
        $stored = (new SecretDigester(['p1' => 'pepper-one'], 'p1'))->digest('s3cret');
        $rotated = new SecretDigester(['p2' => 'pepper-two', 'p1' => 'pepper-one'], 'p2');

        $this->assertTrue($rotated->verify('s3cret', $stored));
        $this->assertTrue($rotated->needsRehash($stored));
        $this->assertStringStartsWith('hmac-sha256:p2:', $rotated->digest('s3cret'));
    }

    public function test_unknown_pepper_or_format_never_verifies(): void
    {
        $stored = (new SecretDigester(['p1' => 'pepper-one'], 'p1'))->digest('s3cret');
        $other = new SecretDigester(['p2' => 'pepper-two'], 'p2');

        $this->assertFalse($other->verify('s3cret', $stored));
        $this->assertFalse($other->verify('s3cret', 's3cret'));
        $this->assertFalse($other->verify('s3cret', hash('sha256', 's3cret')));
    }

    public function test_supported_formats(): void
    {
        $this->assertTrue(SecretDigester::isSupported('hmac-sha256:p1:abc'));
        $this->assertFalse(SecretDigester::isSupported('hmac-sha256:p1:'));
        $this->assertFalse(SecretDigester::isSupported('$argon2id$v=19$m=1024,t=1,p=1$abc'));
        $this->assertFalse(SecretDigester::isSupported(hash('sha256', 'plain')));
    }

    public function test_current_pepper_must_be_on_the_ring(): void
    {
        $this->expectException(InvalidArgumentException::class);
        new SecretDigester(['p1' => 'pepper-one'], 'p2');
    }

    public function test_from_config_with_peppers(): void
    {
        $config = $this->createMock(AppConfig::class);
        $config->method('get')->willReturnCallback(fn (string $name, mixed $def = null) => match ($name) {
            'security.digest.peppers' => 'p2:cGVwcGVyLXR3bw==, p1:cGVwcGVyLW9uZQ==',
            'security.digest.current' => 'p2',
            default => $def,
        });

        $digester = SecretDigester::fromConfig($config);

        $this->assertStringStartsWith('hmac-sha256:p2:', $digester->digest('s3cret'));
        $this->assertFalse($digester->usesDefaultPepper());
    }

    public function test_from_config_without_peppers_uses_the_default_one(): void
    {
        $config = $this->createMock(AppConfig::class);
        $config->method('get')->willReturnCallback(fn (string $name, mixed $def = null) => $def);

        $digester = SecretDigester::fromConfig($config);

        $this->assertStringStartsWith('hmac-sha256:' . SecretDigester::DEFAULT_PEPPER_ID . ':', $digester->digest('s3cret'));
        $this->assertTrue($digester->usesDefaultPepper());
    }
}
